// Complete replacement code for n8n node: Validate Preference Analysis

const envelope = $('When Executed by Another Workflow').first().json;
let data = $input.first().json;
if (data && typeof data.output === 'object' && !Array.isArray(data.output)) data = data.output;

function fail(message) { throw new Error(`[preferences] ${message}`); }
function isObject(value) { return value !== null && typeof value === 'object' && !Array.isArray(value); }
function requireExactKeys(object, required) {
  if (!isObject(object)) fail('Output must be one JSON object.');
  const actual = Object.keys(object);
  const missing = required.filter((key) => !(key in object));
  const extra = actual.filter((key) => !required.includes(key));
  if (missing.length) fail(`Missing keys: ${missing.join(', ')}`);
  if (extra.length) fail(`Unexpected keys: ${extra.join(', ')}`);
}
function requireString(key) { if (typeof data[key] !== 'string' || data[key].trim() === '') fail(`${key} must be a non-empty string.`); }
function requireStringArray(key) { if (!Array.isArray(data[key]) || data[key].some((value) => typeof value !== 'string')) fail(`${key} must be an array of strings.`); }
function normalizeUrl(value) { return String(value || '').trim().replace(/\/$/, ''); }
function hostname(value) {
  const raw = String(value || '').trim();
  const match = raw.match(/^https?:\/\/([^/?#]+)/i);
  if (!match) return '';
  const authority = match[1].toLowerCase();
  if (authority.includes('@')) return '';
  return authority.replace(/:\d+$/, '').replace(/\.$/, '');
}

const required = ['company_name','position','salary','location','preference_matches','preference_misses','potential_preference_matches','preferences_rating','references','years_of_experience','red_flags'];
requireExactKeys(data, required);
for (const key of ['company_name','position','salary','location','years_of_experience']) requireString(key);
for (const key of ['preference_matches','preference_misses','potential_preference_matches','references']) requireStringArray(key);
if (!Number.isInteger(data.preferences_rating) || data.preferences_rating < 0 || data.preferences_rating > 5) fail('preferences_rating must be an integer from 0 through 5.');
if (!Array.isArray(data.red_flags)) fail('red_flags must be an array.');

const allowedCategories = new Set(['salary','satisfaction','layoffs_or_reorganization','financial_instability','team_elimination','leadership_disruption']);
const suppliedUrls = new Set((envelope.research?.results || []).map((result) => normalizeUrl(result.url)).filter(Boolean));
const postingUrl = normalizeUrl(envelope.job?.link || envelope.job?.job_url);
if (postingUrl) suppliedUrls.add(postingUrl);
const derivedFlags = [];
for (const flag of data.red_flags) {
  requireExactKeys(flag, ['category','evidence','source_urls','official_source','published_salary_max','market_salary','employee_rating','documented_decline','acute_impact']);
  if (!allowedCategories.has(flag.category)) fail(`Invalid red-flag category: ${flag.category}`);
  if (typeof flag.evidence !== 'string' || flag.evidence.trim() === '') fail('Every red flag requires evidence.');
  if (!Array.isArray(flag.source_urls) || flag.source_urls.length === 0 || flag.source_urls.some((url) => typeof url !== 'string')) fail('Every red flag requires supplied source URLs.');
  const urls = [...new Set(flag.source_urls.map(normalizeUrl).filter(Boolean))];
  if (urls.length !== flag.source_urls.length) fail('Red-flag source URLs must be non-empty and unique.');
  for (const url of urls) if (!suppliedUrls.has(url)) fail(`Red-flag URL was not supplied: ${url}`);
  if (typeof flag.official_source !== 'boolean' || typeof flag.documented_decline !== 'boolean' || typeof flag.acute_impact !== 'boolean') fail('Red-flag boolean fields are invalid.');
  for (const key of ['published_salary_max','market_salary','employee_rating']) {
    if (flag[key] !== null && (typeof flag[key] !== 'number' || !Number.isFinite(flag[key]) || flag[key] < 0)) fail(`${key} must be null or a non-negative number.`);
  }
  const independentDomains = new Set(urls.map(hostname).filter(Boolean));
  const sourceThreshold = flag.official_source || independentDomains.size >= 2;
  let severity = null;
  if (flag.category === 'salary') {
    if (flag.published_salary_max === null || flag.market_salary === null) fail('Salary red flags require published_salary_max and market_salary.');
    if (flag.market_salary <= 0 || flag.published_salary_max >= flag.market_salary * 0.85) fail('Salary red flag does not meet the more-than-15%-below-market threshold.');
    severity = 'material';
  } else if (flag.category === 'satisfaction') {
    if (!((flag.employee_rating !== null && flag.employee_rating < 3.5) || flag.documented_decline)) fail('Satisfaction red flag lacks a sub-3.5 rating or documented decline.');
    severity = 'material';
  } else if (['layoffs_or_reorganization','leadership_disruption'].includes(flag.category)) {
    if (!sourceThreshold) fail(`${flag.category} requires an official source or two independent supplied domains.`);
    severity = flag.category === 'layoffs_or_reorganization' && flag.acute_impact ? 'acute' : 'material';
  } else if (['financial_instability','team_elimination'].includes(flag.category)) {
    if (!sourceThreshold) fail(`${flag.category} requires an official source or two independent supplied domains.`);
    severity = 'acute';
  }
  derivedFlags.push({...flag, derived_severity: severity});
}
const normalizedFlags = derivedFlags.map((flag) => `${flag.category}|${flag.evidence.trim().toLowerCase()}`);
if (new Set(normalizedFlags).size !== normalizedFlags.length) fail('Duplicate red flags are not allowed.');

const buckets = {matches:data.preference_matches, misses:data.preference_misses, potentials:data.potential_preference_matches};
const allEntries = [...buckets.matches, ...buckets.misses, ...buckets.potentials];
const allowedLabels = /^\[(ELIGIBILITY|DOMAIN|COLLABORATION|GROWTH|DREAM_ROLE|SALARY|SATISFACTION|CULTURE|HEALTH|SECURITY_CULTURE)\]/;
for (const entry of allEntries) if (!allowedLabels.test(entry)) fail(`Invalid preference entry label: ${entry}`);
const eligibilityEntries = allEntries.filter((entry) => entry.startsWith('[ELIGIBILITY]'));
if (eligibilityEntries.length !== 1) fail(`Expected exactly one [ELIGIBILITY] entry; received ${eligibilityEntries.length}.`);
if (!allEntries.some((entry) => entry.startsWith('[SALARY]'))) fail('At least one [SALARY] entry is required.');
const eligibility = eligibilityEntries[0];
const confirmed = eligibility.startsWith('[ELIGIBILITY] Confirmed:');
const failed = eligibility.startsWith('[ELIGIBILITY] Failed:');
const unverified = eligibility.startsWith('[ELIGIBILITY] Unverified:');
if (!confirmed && !failed && !unverified) fail('Eligibility entry must be Confirmed, Failed, or Unverified.');
if (confirmed && !buckets.matches.includes(eligibility)) fail('Confirmed eligibility must be in preference_matches.');
if (failed && !buckets.misses.includes(eligibility)) fail('Failed eligibility must be in preference_misses.');
if (unverified && !buckets.potentials.includes(eligibility)) fail('Unverified eligibility must be in potential_preference_matches.');

let expectedRating = 0;
if (confirmed) {
  const labels = ['[DOMAIN]','[COLLABORATION]','[GROWTH]','[DREAM_ROLE]'];
  const baseline = 1 + labels.filter((label) => buckets.matches.some((entry) => entry.startsWith(label))).length;
  const materialCount = derivedFlags.filter((flag) => flag.derived_severity === 'material').length;
  const hasAcute = derivedFlags.some((flag) => flag.derived_severity === 'acute');
  const cap = hasAcute || materialCount >= 2 ? 1 : materialCount === 1 ? 2 : 5;
  expectedRating = Math.min(baseline, cap);
}
if (data.preferences_rating !== expectedRating) fail(`preferences_rating must be ${expectedRating} from validated eligibility, dimensions, and red-flag thresholds.`);

for (const ref of data.references) if (!suppliedUrls.has(normalizeUrl(ref))) fail(`Reference was not supplied by web research or the posting: ${ref}`);
return [{ json: {...data, red_flags: derivedFlags} }];

const envelope = $('When Executed by Another Workflow').first().json;
const analysis = $input.first().json;
const source = envelope.job || {};
const jobId = String(source.job_id || '').trim();
const jobUrl = String(source.link || source.job_url || '').trim();
if (!/^\d{6,20}$/.test(jobId)) throw new Error('[preferences] Missing canonical LinkedIn job_id.');
if (!jobUrl) throw new Error('[preferences] Missing canonical LinkedIn job URL.');
const postedDate = String(source.pubDate || source.isoDate || '').trim() || null;
const result = {
  ...analysis,
  job_id: jobId,
  posted_date: postedDate,
  job_url: jobUrl,
};
return [{
  json: {
    ...envelope,
    results: { ...(envelope.results || {}), preferences: result },
  },
}];
